<script setup lang="ts">
import PageHeader from '../workspace/PageHeader.vue'
import {onMounted,ref} from 'vue'
import {api,authorizationHeaders,authGeneration,refreshAuth} from '../api'
import {backendBase} from '../platform/bridge'
import {useRequestScope} from '../platform/request-scope'
import {messages as t} from './locale'
import ProductNav from './ProductNav.vue'
import type {KnowledgeDoc,KnowledgeHit,ProductAccount} from './types'
const docs=ref<KnowledgeDoc[]>([]),hits=ref<KnowledgeHit[]>([]),query=ref(''),error=ref(''),notice=ref(''),busy=ref(false),searched=ref(false),admin=ref(false),capture=useRequestScope()
let searchVersion=0
async function load(){const scope=capture();try{const [result,profile]=await Promise.all([api<{items:KnowledgeDoc[]}>('/product/knowledge'),api<ProductAccount>('/product/account')]);if(scope.valid()){docs.value=result.items;admin.value=profile.role==='ADMIN'}}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const scope=capture();busy.value=true;error.value='';const body=new FormData();body.append('file',file);body.append('purpose','knowledge');try{await api('/product/objects',{method:'POST',body});if(scope.valid()){notice.value='资料已保存并可检索';await load()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false;(event.target as HTMLInputElement).value=''}}
async function search(){const scope=capture(),attempt=++searchVersion;busy.value=true;error.value='';try{const result=await api<{items:KnowledgeHit[]}>('/product/knowledge/search',{method:'POST',body:{query:query.value,scope:'author'}});if(scope.valid()&&attempt===searchVersion){hits.value=result.items;searched.value=true}}catch(e){if(scope.valid()&&attempt===searchVersion)error.value=(e as Error).message}finally{if(scope.valid()&&attempt===searchVersion)busy.value=false}}
async function remove(doc:KnowledgeDoc){if(!confirm(`删除“${doc.title}”及其检索资料？`))return;const scope=capture();busy.value=true;try{await api('/product/objects/'+doc.objectId,{method:'DELETE'});if(scope.valid()){hits.value=hits.value.filter(h=>h.documentId!==doc.id);await load()}}catch(e){if(scope.valid())error.value=(e as Error).message}finally{if(scope.valid())busy.value=false}}
async function download(doc:KnowledgeDoc){const scope=capture(),base=backendBase(),epoch=authGeneration();try{let response=await fetch(base+'/api/reader/v1/product/objects/'+doc.objectId+'/content',{headers:authorizationHeaders(),credentials:'include'});if(!scope.valid()||base!==backendBase()||epoch!==authGeneration())return;if(response.status===401&&await refreshAuth()){if(!scope.valid())return;response=await fetch(base+'/api/reader/v1/product/objects/'+doc.objectId+'/content',{headers:authorizationHeaders(),credentials:'include'})}if(!response.ok)throw new Error('下载失败，请重新加载资料后重试');const blob=await response.blob();if(!scope.valid())return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=doc.title;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(scope.valid())error.value=(e as Error).message}}
onMounted(load)
</script>
<template><div class="product-page"><PageHeader title="参考资料" description="保存创作资料，在需要时找到出处。"/><p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="product-hint" role="status">{{notice}}</p><div class="product-grid"><section class="product-card"><h2>{{t.upload}}</h2><label>选择资料文件<input type="file" accept=".txt,.md,.docx,.epub" :disabled="busy" @change="upload"></label><p class="product-note">支持 TXT、Markdown、Word、EPUB，每个文件最多 8 MB。资料只对当前账号开放。</p><p class="product-note">上传资料供你查阅；角色在故事中只能检索已获知的线索。</p></section><section class="product-card"><h2>{{t.search}}</h2><form @submit.prevent="search"><label>关键词<input v-model="query" required maxlength="100" placeholder="例如：人物关系、场景设定"></label><button class="primary" :disabled="busy">{{busy?'检索中…':t.search}}</button></form></section><section class="product-card product-span"><h2>我的资料</h2><p v-if="!docs.length" class="product-empty">还没有资料。上传一份设定或参考文档即可开始。</p><article v-for="doc in docs" :key="doc.id" class="list-item"><strong>{{doc.title}}</strong><p class="product-note">{{doc.chunks}} 段资料 · 版本 {{doc.sourceVersion.slice(0,12)}}</p><div class="product-actions"><button @click="download(doc)">{{t.download}}</button><button class="danger" :disabled="busy" @click="remove(doc)">{{t.remove}}</button></div></article></section><section v-if="searched" class="product-card product-span"><h2>检索结果</h2><p v-if="!hits.length" class="product-empty">没有找到匹配资料，请换一个关键词。</p><article v-for="hit in hits" :key="hit.blockId" class="product-search-hit"><strong>{{hit.title}}</strong><blockquote>{{hit.text}}</blockquote><small class="product-note">{{t.source}} {{hit.sourceVersion.slice(0,12)}} · 引用 {{hit.blockId}}</small></article></section></div></div></template>
